import React, { useEffect, useRef, useState } from 'react';
import './JournalSection.css';

const JournalSection = () => {
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef(null);

  const articles = [
    {
      title: 'Membangun identitas yang terasa autentik',
      description: 'Identitas bukan hanya logo. Ia adalah rangkaian keputusan yang membuat sebuah brand terasa konsisten.',
      label: 'Catatan desain',
      image: 'https://images.unsplash.com/photo-1493612276216-ee3925520721?w=600&h=400&fit=crop'
    },
    {
      title: 'Desain yang dapat diakses semua orang',
      description: 'Kontras, navigasi yang jelas, dan struktur konten yang baik membuat pengalaman lebih ramah bagi semua pengguna.',
      label: 'Catatan desain',
      image: 'https://images.unsplash.com/photo-1581291518857-4e27b48ff24e?w=600&h=400&fit=crop'
    },
    {
      title: 'Melihat ulang proses kreatif',
      description: 'Proses kreatif dimulai dari pertanyaan yang tepat, bukan dari jawaban yang paling cepat.',
      label: 'Catatan desain',
      image: 'https://images.unsplash.com/photo-1455849318743-b2233052fcff?w=600&h=400&fit=crop'
    }
  ];

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) setIsVisible(true);
      },
      { threshold: 0.2 }
    );

    if (sectionRef.current) observer.observe(sectionRef.current);
    return () => observer.disconnect();
  }, []);

  return (
    <section 
      ref={sectionRef} 
      id="journal"
      className={`journal-section ${isVisible ? 'visible' : ''}`}
    >
      <div className="journal-container">
        <div className="journal-header">
          <span className="section-badge">Catatan desain</span>
          <h2 className="journal-title">Ide & perspektif</h2>
          <p className="journal-description">
            Hal-hal yang membentuk cara saya melihat dan merancang.
          </p>
        </div>

        <div className="articles-grid">
          {articles.map((article, index) => (
            <article 
              key={index} 
              className="article-card"
              style={{ animationDelay: `${index * 0.1}s` }}
            >
              <div className="article-image-wrapper">
                <img src={article.image} alt={article.title} className="article-image" />
              </div>
              <div className="article-content">
                <span className="article-label">{article.label}</span>
                <h3 className="article-title">{article.title}</h3>
                <p className="article-description">{article.description}</p>
                <a href="#" className="article-link">Baca selengkapnya →</a>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
};

export default JournalSection;
